package com.vandorlabs.neoforge.segmented;
import java.util.*;
import net.minecraft.core.Direction;
import net.minecraft.world.entity.player.Player;
import com.vandorlabs.redstone.ChannelList;
import com.vandorlabs.neoforge.redstone.NativeRedstoneChannels;
/** Bounded loaded-only topology and source-equivalent authoritative operations. */
public final class NativeSegmentedDoorLifecycle {
 public static void refreshColumn(NativeSegmentedDoorEntity tile){if(!tile.installed()||tile.getLevel().isClientSide)return;var level=tile.getLevel();var top=tile;int count=1;NativeSegmentedDoorEntity next;while((next=top.neighbor(Direction.UP))!=null){if(++count>32)return;top=next;}List<NativeSegmentedDoorEntity> members=new ArrayList<>();var source=top;for(var member=top;member!=null;member=member.neighbor(Direction.DOWN)){if(members.size()>=32)return;members.add(member);if(member.formed&&(!source.formed||member.configured&&!source.configured||member.height>source.height))source=member;}
  boolean topology=false;for(int i=0;i<members.size();i++)if(!members.get(i).formed||members.get(i).topOffset!=i||members.get(i).height!=members.size())topology=true;
  if(topology){double current=source.pose(0);long sequence=source.sequence+1;boolean target=source.targetOpen,local=source.localRedstone,opens=source.signalOpens,custom=source.configured;int speed=source.ticksPerSection,texture=source.texture;var channels=source.channels;var settings=source.settings;UUID id=source.identity;
   for(int i=0;i<members.size();i++){var t=members.get(i);boolean previous=t.formed||t.configured;t.topOffset=i;t.height=members.size();t.formed=true;t.from=current;t.targetOpen=target;t.started=level.getGameTime();t.duration=Math.max(1,(int)Math.ceil(t.height*speed*Math.abs((target?1:0)-current)));t.sequence=sequence;t.identity=id;t.channels=channels;t.ticksPerSection=speed;t.localRedstone=local;t.signalOpens=opens;t.configured=custom||t.configured;t.texture=texture;t.settings=previous?t.settings.shared(settings):settings;}}
  refreshSpan(top,topology);if(topology)for(var t:members)NativeRedstoneChannels.channelsChanged(t);
 }
 public static List<NativeSegmentedDoorEntity> roots(NativeSegmentedDoorEntity tile){if(!tile.installed())throw new IllegalArgumentException("Segmented door is not installed");var root=tile.root();if(!root.formed)throw new IllegalArgumentException("Complete the segmented column (maximum 32 sections)");LinkedHashSet<NativeSegmentedDoorEntity> found=new LinkedHashSet<>();ArrayDeque<NativeSegmentedDoorEntity> queue=new ArrayDeque<>();found.add(root);queue.add(root);while(!queue.isEmpty()){var current=queue.removeFirst();for(Direction side:new Direction[]{current.facing().getClockWise(),current.facing().getCounterClockWise()}){if(!tile.getLevel().hasChunkAt(current.getBlockPos().relative(side)))throw new IllegalArgumentException("Load the complete segmented door before changing it");var other=current.neighbor(side);if(other==null||other.topOffset!=0||other.height!=root.height||found.contains(other))continue;if(found.size()>=32)throw new IllegalArgumentException("Segmented door supports at most 32 linked columns");found.add(other);queue.add(other);}}return new ArrayList<>(found);}
 static List<NativeSegmentedDoorEntity> columnMembers(NativeSegmentedDoorEntity tile){List<NativeSegmentedDoorEntity> out=new ArrayList<>();var owner=tile.root();for(int row=0;row<owner.height;row++){var t=NativeSegmentedDoorEntity.at(tile.getLevel(),owner.getBlockPos().below(row));if(t!=null)out.add(t);}return out;}
 static List<NativeSegmentedDoorEntity> members(List<NativeSegmentedDoorEntity> roots){List<NativeSegmentedDoorEntity> all=new ArrayList<>();for(var root:roots)for(int row=0;row<root.height;row++){var t=NativeSegmentedDoorEntity.at(root.getLevel(),root.getBlockPos().below(row));if(t==null||t.facing()!=root.facing()||t.height!=root.height||t.topOffset!=row)throw new IllegalArgumentException("Load the complete segmented door before changing it");all.add(t);}return all;}
 private static void refreshSpan(NativeSegmentedDoorEntity tile,boolean force){List<NativeSegmentedDoorEntity> roots;try{roots=roots(tile);}catch(IllegalArgumentException incomplete){return;}Direction right=tile.facing().getClockWise();roots.sort(Comparator.comparingInt(t->t.getBlockPos().getX()*right.getStepX()+t.getBlockPos().getZ()*right.getStepZ()));List<NativeSegmentedDoorEntity> all=members(roots);boolean changed=force;for(int i=0;i<roots.size();i++)for(var t:columnMembers(roots.get(i))){changed|=t.column!=i||t.columns!=roots.size();t.column=i;t.columns=roots.size();}if(changed)NativeSegmentedDoorEntity.publish(all);}
 static void permissions(NativeSegmentedDoorEntity owner,Player player,List<NativeSegmentedDoorEntity> all){if(player==null||!player.isAlive()||player.isSpectator()||player.level()!=owner.getLevel())throw new IllegalArgumentException("Segmented door is protected");for(var t:all)if(!t.installed()||!t.getLevel().mayInteract(player,t.getBlockPos())||!player.mayUseItemAt(t.getBlockPos(),Direction.UP,player.getMainHandItem()))throw new IllegalArgumentException("Segmented door is protected");}
 public static void operate(NativeSegmentedDoorEntity tile,Player player,boolean open){if(tile.root().settings.activation>0)throw new IllegalArgumentException("This door is controlled by redstone");var roots=roots(tile);permissions(tile,player,members(roots));moveTogether(roots,open);}
 public static void configure(NativeSegmentedDoorEntity tile,Player player,ChannelList next,int ticks,boolean local,boolean opens,int texture,NativeSegmentedDoorSettings settings,boolean part){configure(tile,player,next,ticks,local,opens,texture,settings,part,null);}
 public static void configure(NativeSegmentedDoorEntity tile,Player player,ChannelList next,int ticks,boolean local,boolean opens,int texture,NativeSegmentedDoorSettings settings,boolean part,com.vandorlabs.segmented.SegmentedCellArtwork artwork){if(artwork!=null&&artwork.overridden&&!NativeSegmentedDoorEntity.validTexture(artwork.choice))throw new IllegalArgumentException("Invalid segment artwork");if(next==null||ticks<5||ticks>30||!NativeSegmentedDoorEntity.validTexture(texture)||settings==null)throw new IllegalArgumentException("Invalid Segmented Door settings");var roots=roots(tile);var all=members(roots);permissions(tile,player,all);for(var t:all){t.channels=next;t.ticksPerSection=ticks;t.localRedstone=local;t.signalOpens=opens;t.texture=texture;if(t==tile&&artwork!=null)t.cellArtwork=artwork;t.settings=part&&t!=tile?t.settings.shared(settings):settings;t.configured=true;}NativeSegmentedDoorEntity.publish(all);for(var t:all)NativeRedstoneChannels.channelsChanged(t);refreshPower(tile);}
 public static void configureLegacy(NativeSegmentedDoorEntity tile,Player player,ChannelList next,int ticks,boolean local,boolean opens){if(next==null||ticks<5||ticks>30)throw new IllegalArgumentException("Invalid segmented door settings");var roots=roots(tile);var all=members(roots);permissions(tile,player,all);for(var t:all){t.channels=next;t.ticksPerSection=ticks;t.localRedstone=local;t.signalOpens=opens;t.settings=t.settings.activation(-1);t.configured=true;}NativeSegmentedDoorEntity.publish(all);for(var t:all)NativeRedstoneChannels.channelsChanged(t);refreshPower(tile);}
 public static void configureTexture(NativeSegmentedDoorEntity tile,Player player,int choice){if(!NativeSegmentedDoorEntity.validTexture(choice))throw new IllegalArgumentException("Invalid Segmented Door texture");var all=members(roots(tile));permissions(tile,player,all);for(var t:all){t.texture=choice;t.clearCellArtwork();t.configured=true;}NativeSegmentedDoorEntity.publish(all);}
 static void refreshPower(NativeSegmentedDoorEntity tile){if(!tile.installed()||tile.getLevel().isClientSide)return;List<NativeSegmentedDoorEntity> roots,all;try{roots=roots(tile);all=members(roots);}catch(IllegalArgumentException incomplete){return;}boolean signal=false,enabled=false;for(var t:all){enabled|=t.localRedstone||!t.channels.isEmpty();signal|=t.channelSignal||t.localRedstone&&com.vandorlabs.neoforge.redstone.NativeLoadedRedstonePower.level(t.getLevel(),t.getBlockPos())>0;}int activation=tile.root().settings.activation;if(activation==0)return;if(enabled||activation>0)moveTogether(roots,activation<0?signal==tile.root().signalOpens:activation==1?signal:!signal);}
 private static void moveTogether(List<NativeSegmentedDoorEntity> roots,boolean open){boolean changing=false;for(var t:roots)changing|=t.targetOpen!=open;if(!changing)return;var leader=roots.get(0);double current=leader.pose(0);long start=leader.getLevel().getGameTime();int ticks=leader.ticksPerSection,duration=Math.max(1,(int)Math.ceil((leader.settings.direction<2?leader.height:leader.columns)*ticks*Math.abs((open?1:0)-current)));UUID motion=UUID.randomUUID();var all=members(roots);for(var owner:roots){long sequence=owner.sequence+1;for(var t:columnMembers(owner)){t.motionIdentity=motion;t.targetOpen=open;t.from=current;t.started=start;t.duration=duration;t.ticksPerSection=ticks;t.sequence=sequence;}}NativeSegmentedDoorEntity.publishMotion(all);}
 private NativeSegmentedDoorLifecycle(){}
}
